// Sample buggy file for testing the bug-fixer agent

function processUsers(users) {
  // BUG: no null check
  for (let i = 0; i <= users.length; i++) {  // BUG: off-by-one error
    const user = users[i];
    console.log("Processing: " + user.name);

    // BUG: comparing string to number without conversion
    if (user.age == "18") {
      console.log("Adult user found");
    }

    // BUG: modifying array while iterating
    if (user.inactive) {
      users.splice(i, 1);
    }
  }

  return users;
}

// BUG: unused variable and potential memory leak
function fetchData(url) {
  let cache = {};
  const result = fetch(url)
    .then(res => res.json())
    .then(data => {
      cache[url] = data;  // grows unbounded
      return data;
    });
  // BUG: not returning the promise
}

// TODO: add input validation
// FIXME: this function has race conditions
async function updateCounter(id) {
  const current = await getCounter(id);
  await setCounter(id, current + 1);
}

module.exports = { processUsers, fetchData, updateCounter };

