// Session persistence demo: continue a conversation across multiple queries
import { query } from "@anthropic-ai/claude-agent-sdk";

async function runQuery(prompt, sessionId, options = {}) {
  let result = "";
  const queryOptions = {
    prompt,
    options: {
      settingSources: ["project"],
      allowedTools: ["Read", "Write", "Edit", "Bash", "Glob", "Grep"],
      cwd: process.cwd(),
      ...options,
    },
  };
  if (sessionId) queryOptions.options.sessionId = sessionId;

  for await (const message of query(queryOptions)) {
    if ("result" in message) result = message.result;
    if ("sessionId" in message) sessionId = message.sessionId;
  }
  return { result, sessionId };
}

async function main() {
  console.log("--- Session Demo (Claude Code) ---\n");

  // First query: analyze the project
  console.log("Step 1: Analyzing project...");
  const { result: r1, sessionId } = await runQuery(
    "Look at this project structure and tell me what it does. Remember the key files.",
  );
  console.log(r1);
  console.log(`\n(Session ID: ${sessionId})\n`);

  // Second query: follow-up using the same session (Claude remembers context)
  console.log("Step 2: Follow-up question (same session)...");
  const { result: r2 } = await runQuery(
    "Based on what you just saw, what improvements would you suggest?",
    sessionId,
  );
  console.log(r2);
}

main().catch(console.error);

